use zopro_bn254::Fr;
use serde_json::json;
#[derive(Default,Debug,PartialEq,Eq,Clone)]
pub struct Counts {pub arrivals:usize,pub first_writes:usize,pub affine_updates:usize,pub batches:usize,pub full_batches:usize,pub projective_arrivals:usize,pub projective_accumulator_adds:usize,pub finish_merges:usize,pub queue_pushes:usize,pub busy_checks:usize,pub drain_inspections:usize,pub drained:usize,pub max_batch:usize,pub max_queue:usize,pub histogram:std::collections::BTreeMap<usize,usize>}
impl Counts{pub fn json(&self)->serde_json::Value{json!({"arrivals":self.arrivals,"first_writes":self.first_writes,"affine_updates":self.affine_updates,"batches":self.batches,"full_batches":self.full_batches,"projective_arrivals":self.projective_arrivals,"projective_accumulator_adds":self.projective_accumulator_adds,"finish_merges":self.finish_merges,"queue_pushes":self.queue_pushes,"busy_checks":self.busy_checks,"drain_inspections":self.drain_inspections,"drained":self.drained,"max_batch":self.max_batch,"max_queue":self.max_queue,"batch_histogram":self.histogram})}}
pub struct Model {pub counts:Counts,occupied:Vec<bool>,affine:Vec<Fr>,projective:Vec<Fr>,projective_used:Vec<bool>,busy:Vec<bool>,batch:Vec<(u32,Fr)>,queue:Vec<(u32,Fr)>,size:usize,scan:bool}
impl Model{
 pub fn new(half:usize,size:usize,scan:bool)->Self{assert!(half>0&&size>=8);Self{counts:Counts::default(),occupied:vec![false;half],affine:vec![Fr::ZERO;half],projective:vec![Fr::ZERO;half],projective_used:vec![false;half],busy:vec![false;half],batch:Vec::with_capacity(size),queue:Vec::with_capacity(size),size,scan}}
 fn busy(&mut self,b:usize)->bool{self.counts.busy_checks+=1;self.busy[b]}
 fn add(&mut self,encoded:u32,p:Fr){let b=(encoded&0x7fffffff)as usize;let p=if encoded>>31!=0{-p}else{p};if !self.occupied[b]{self.occupied[b]=true;self.affine[b]=p;self.counts.first_writes+=1;return}assert!(!self.busy[b]);self.busy[b]=true;self.batch.push((b as u32,p));self.counts.max_batch=self.counts.max_batch.max(self.batch.len());assert!(self.batch.len()<=self.size);}
 fn execute(&mut self){if self.batch.is_empty(){return}self.counts.batches+=1;self.counts.full_batches+=usize::from(self.batch.len()==self.size);self.counts.affine_updates+=self.batch.len();*self.counts.histogram.entry(self.batch.len()).or_default()+=1;for &(b,p)in &self.batch{assert!(self.busy[b as usize]);self.affine[b as usize]+=p;self.busy[b as usize]=false;}self.batch.clear();}
 fn flush_queue(&mut self){for &(encoded,p)in &self.queue{let b=(encoded&0x7fffffff)as usize;self.counts.projective_arrivals+=1;if self.projective_used[b]{self.counts.projective_accumulator_adds+=1;}else{self.projective_used[b]=true;}self.projective[b]+=if encoded>>31!=0{-p}else{p};}self.queue.clear();}
 fn scan_queue(&mut self){let n=self.queue.len();for i in(0..n).rev(){let(encoded,p)=self.queue[i];self.counts.drain_inspections+=1;if self.busy((encoded&0x7fffffff)as usize){continue}self.queue.swap_remove(i);self.counts.drained+=1;self.add(encoded,p);}}
 pub fn feed(&mut self,arrivals:&[(u32,Fr)]){for &(encoded,p)in arrivals{let b=(encoded&0x7fffffff)as usize;self.counts.arrivals+=1;if self.busy(b){self.queue.push((encoded,p));self.counts.queue_pushes+=1;self.counts.max_queue=self.counts.max_queue.max(self.queue.len());assert!(self.queue.len()<self.size);if self.queue.len()==self.size-1{self.flush_queue();}continue}self.add(encoded,p);if self.batch.len()==self.size{self.execute();if self.scan{self.scan_queue()}else{let before=self.queue.len();let checks=self.counts.busy_checks;self.take_from_queue();self.counts.drain_inspections+=self.counts.busy_checks-checks;self.counts.drained+=before-self.queue.len();}}}self.execute();self.flush_queue();assert!(self.batch.is_empty()&&self.queue.is_empty());assert!(self.busy.iter().all(|b|!*b));}
 pub fn phi(&mut self,lambda:Fr){for v in self.affine.iter_mut().chain(&mut self.projective){*v*=lambda;}}
 pub fn finish(mut self)->(Vec<Fr>,Counts){for b in 0..self.affine.len(){if self.projective_used[b]{self.counts.finish_merges+=1;self.affine[b]+=self.projective[b];}}assert_eq!(self.counts.arrivals,self.counts.first_writes+self.counts.affine_updates+self.counts.projective_arrivals);assert_eq!(self.counts.projective_arrivals,self.counts.projective_accumulator_adds+self.counts.finish_merges);(self.affine,self.counts)}
}
include!("lifo-impl.rs");
